import {assess,annotation} from './game-model.js';
const $=id=>document.getElementById(id),storageKey='los-lunares-site01-annotations-v1';
const embedded=new URLSearchParams(location.search).get('embedded')==='1';
document.body.classList.toggle('embedded',embedded);
// En el rescate sequence=1, la selección es el primer paso, no el final.
if(embedded&&new URLSearchParams(location.search).get('sequence')==='1')$('continue').textContent='Zona lista · pasar al descenso →';

// En la misión, mostrar solo el mapa y las acciones; ampliar datos bajo demanda.
if(embedded){
 const heading=document.createElement('div');heading.className='compact-head';heading.innerHTML='<img src="assets/felicette-terrain.png" alt="Félicette"><div><h1>Elegí una zona candidata</h1><p>Marcá al menos una y revisá tu elección.</p></div><button type="button" id="compactInfoButton">Datos y aportes</button>';
 document.querySelector('main').prepend(heading);
 const info=document.createElement('dialog');info.className='compact-info';info.setAttribute('aria-label','Criterios y aportes del minijuego');info.innerHTML='<div class="compact-info-head"><h2>Datos y criterios</h2><button type="button">Cerrar ✕</button></div>';
 info.append(document.querySelector('.rule').cloneNode(true),document.querySelector('.collaboration'),document.querySelector('.method'));
 document.body.append(info);info.querySelector('.compact-info-head button').onclick=()=>info.close();
 document.getElementById('compactInfoButton').onclick=()=>info.showModal();
}

let dataset,index=0,selected=new Set(),assisted=false,attempt=0,completed=false;
const retryDialog=document.createElement('dialog');retryDialog.className='terrain-retry-dialog';retryDialog.setAttribute('aria-labelledby','terrainRetryTitle');retryDialog.innerHTML='<div class="terrain-retry-intro"><img src="assets/felicette-terrain.png" alt="Félicette te da una pista"><div><span class="eyebrow">UNA PISTA PARA SEGUIR</span><h2 id="terrainRetryTitle">Esa selección necesita cambiar.</h2></div></div><p id="terrainRetryReason"></p><p id="terrainRetryHint"></p><button type="button" class="primary" id="terrainRetryClose">Entendido · elegir de nuevo →</button>';document.body.append(retryDialog);
$('terrainRetryClose').onclick=()=>{retryDialog.close();$('tiles').querySelector('button')?.focus({preventScroll:true});};
function showRetry(result){const candidate=round().tiles.find(t=>t.status==='candidate');const reason=result.review.slice(0,2).map(id=>{const t=round().tiles.find(t=>t.id===id);return `${id}: ${fmt(t.fraction_below_8_deg_percent)}% de píxeles bajo 8° y ${fmt(t.relief_p95_p5_m)} m de relieve local.`;}).join(' ');selected.clear();completed=false;assisted=true;layer();render();$('continue').hidden=true;$('next').hidden=true;$('cellInfo').textContent='Limpiamos la selección. Elegí de nuevo con la pista de Félicette.';$('feedback').className='feedback retry';$('feedback').textContent='Esa selección no cumple todos los criterios. Limpiamos los cuadrantes marcados para que puedas volver a elegir.';$('terrainRetryReason').textContent=reason;const help=attempt>=2&&candidate?`Probá ${candidate.id}: tiene ${fmt(candidate.fraction_below_8_deg_percent)}% de píxeles bajo 8° y ${fmt(candidate.relief_p95_p5_m)} m de relieve local. Seleccionalo y revisá tu elección.`:'Buscá un cuadrante con al menos 80% de píxeles verdes y relieve local de 20 m o menos. No alcanza con que una parte se vea verde. Tocá un cuadrante para leer sus medidas.';$('terrainRetryHint').textContent=help;if(attempt>=2&&candidate){const tile=$('tiles').querySelector(`[data-cell="${candidate.id}"]`);tile?.classList.add('hint-candidate');}if(!retryDialog.open)retryDialog.showModal();}

let saved=[];
try{saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(saved))saved=[];}catch{}
const fmt=n=>Number.isFinite(n)?n.toLocaleString('es-AR',{maximumFractionDigits:1}):'sin datos';
const round=()=>dataset.rounds[index];
function refreshSaved(){ $('savedCount').textContent=saved.length?`${saved.length} elecciones guardadas solo en este navegador.`:'Sin anotaciones guardadas.';$('export').disabled=!saved.length; }
function reset(){selected=new Set();assisted=false;attempt=0;completed=false;$('feedback').textContent='';$('feedback').className='feedback';$('continue').hidden=true;$('next').hidden=true;$('cellInfo').textContent='Tocá un cuadrante para inspeccionarlo.';$('sectorTitle').textContent=round().title;$('roundCount').textContent=`${index+1} / ${dataset.rounds.length}`;layer();render();}
function layer(){if(!dataset)return;assisted=true;$('terrainImage').src=round().slope_image;$('legend').innerHTML='<b class="low">■ &lt;8° · menor inclinación</b><b class="mid">■ 8–15°</b><b class="high">■ ≥15° · mayor inclinación</b> Color por píxel, no una clasificación completa de seguridad.';}

function render(result){$('selectedCount').textContent=selected.size?`${selected.size} cuadrante${selected.size===1?'':'s'} seleccionado${selected.size===1?'':'s'}`:'Sin cuadrantes seleccionados';$('check').disabled=!selected.size||completed;$('tiles').replaceChildren();for(const cell of round().tiles){const button=document.createElement('button');button.className='tile';button.dataset.cell=cell.id;button.setAttribute('aria-pressed',String(selected.has(cell.id)));button.setAttribute('aria-label',`Cuadrante ${cell.id}${selected.has(cell.id)?', seleccionado':''}`);button.innerHTML=`<span>${cell.id}</span>`;if(result&&selected.has(cell.id))button.classList.add(cell.status==='candidate'?'correct':'review');button.onclick=()=>{if(completed)return;selected.has(cell.id)?selected.delete(cell.id):selected.add(cell.id);$('feedback').textContent='';$('cellInfo').textContent=`${cell.id}: pendiente mediana ${fmt(cell.median_slope_deg)}°. ${fmt(cell.fraction_below_8_deg_percent)}% de píxeles bajo 8°. Relieve local P95–P5: ${fmt(cell.relief_p95_p5_m)} m.`;assisted=true;render();};$('tiles').append(button);}}
$('hint').onclick=()=>{assisted=true;layer();$('feedback').className='feedback';$('feedback').textContent='Félicette: buscá sectores con muchos píxeles verdes. Revisá también el relieve local. Una celda puede verse verde en parte y no cumplir el porcentaje del ejercicio.';};
$('check').onclick=()=>{if(!selected.size||completed)return;attempt++;if($('consent').checked){try{if(saved.length>=1000)throw Error('Se alcanzó el límite local de 1000 registros. Exportalos antes de continuar.');const updated=[...saved,annotation(dataset,round(),selected,assisted,attempt)];localStorage.setItem(storageKey,JSON.stringify(updated));saved=updated;refreshSaved();}catch(error){$('savedCount').textContent='No se pudo guardar: '+error.message;}}
const result=assess(round(),selected);completed=result.completed;render(result);$('feedback').className=`feedback ${completed?'success':''}`;
if(completed){$('feedback').textContent=`¡Buena lectura! ${result.correct.join(', ')} cumple${result.correct.length===1?'':'n'} los criterios de esta práctica. Félicette ya tiene una zona candidata para que el equipo la estudie. Todavía faltan rocas, rugosidad y otros análisis.`;$('continue').hidden=!embedded;$('next').hidden=false;$('next').textContent=index===dataset.rounds.length-1?'Volver al primer sector ↺':'Probar otro sector ↗';}
else{showRetry(result);}};
$('continue').onclick=()=>{if(completed&&embedded)window.parent.postMessage({type:'lunar-terrain-complete',version:1,sector_id:round().id,rule_version:dataset.rule_version},location.origin);};
$('next').onclick=()=>{index=(index+1)%dataset.rounds.length;reset();$('sectorTitle').scrollIntoView({behavior:'smooth',block:'start'});};
$('export').onclick=()=>{const data={schema_version:1,purpose:'team_review_not_NASA_submission',exported_at:new Date().toISOString(),notice:'Anotaciones de entrenamiento asistido y autocorregido; no son evidencia independiente ni certificación de seguridad.',records:saved};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='los-lunares-anotaciones-site01.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
refreshSaved();
fetch('assets/desafios.json').then(r=>{if(!r.ok)throw Error('No se pudieron cargar los sectores');return r.json();}).then(data=>{dataset=data;const requested=Number(new URLSearchParams(location.search).get('sector')||0);index=Number.isInteger(requested)&&requested>=0&&requested<dataset.rounds.length?requested:0;reset();}).catch(error=>{$('feedback').textContent=error.message;$('sectorTitle').textContent='No pudimos abrir el terreno';});
